import json, re, sys, subprocess

R="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
MAIN="/tmp/ross-main"
ep=sys.argv[1]
beats=json.load(open("/tmp/beats.json"))
path=MAIN+"/"+ep.replace("/","/")+".md"
content=open(path).read()
have=set(re.findall(r"@ ([0-9a-f]{40})", content))
allb=[b for b in beats if b["ep"]==ep]
missing=[b for b in allb if b["sha"] not in have]
missing.sort(key=lambda b:(b["ts"], b["sha"]))
present={b["sha"] for b in allb}
for _ in range(len(missing)+1):
    changed=False
    for i,b in enumerate(missing):
        t=b["reply"]
        if t in present and t!=b["sha"]:
            try: j=[x["sha"] for x in missing].index(t)
            except ValueError: continue
            if j>i:
                missing.insert(j, missing.pop(i)); changed=True
    if not changed: break

def entry(b):
    spk=b["branch"].split("/")[1].capitalize()
    ts=b["ts"].replace("+00:00","Z")
    return "**%s** (%s)\n\nSource: %s @ %s\n\n%s\n" % (spk, ts, b["branch"], b["sha"], b["text"])

if missing:
    new="\n".join(entry(b) for b in missing)
    content=content.rstrip("\n")+"\n\n"+new
    open(path,"w").write(content)
print(ep, "appended", len(missing))
for b in missing: print("  ", b["ts"], b["branch"], b["sha"])
